 "content": "def transform(grid):
    # Collapse each maximal run of identical adjacent rows, then columns.
    rows = []
    for row in grid:
        row = list(row)
        if not rows or row != rows[-1]:
            rows.append(row)
    if not rows:
        return []
    cols = []
    for j in range(len(rows[0])):
        col = tuple(row[j] for row in rows)
        if not cols or col != cols[-1]:
            cols.append(col)
    return [[col[i] for col in cols] for i in range(len(rows))]
